def fetch(url,timeout=10):
    req=urllib.request.Request(url,headers={"User-Agent":AGENT,"Accept-Language":"uk","Accept":"application/json,image/png,*/*"})
    with urllib.request.urlopen(req,timeout=timeout) as response: return response.read()

def world(lat,lon,z):
    lat=max(-85.0511,min(85.0511,lat)); n=256*2**z
    return (lon+180)/360*n,(1-math.asinh(math.tan(math.radians(lat)))/math.pi)/2*n

def geo(x,y,z):
    n=256*2**z
    return math.degrees(math.atan(math.sinh(math.pi*(1-2*y/n)))),x/n*360-180

def distance(a,b):
    p1,p2=map(math.radians,(a[0],b[0])); dp=p2-p1; dl=math.radians(b[1]-a[1]); h=math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 12742000*math.asin(min(1,math.sqrt(h)))

def geocode(text):
    if not text.strip(): raise ValueError("Адресу не введено")
    query=urllib.parse.urlencode({"q":text,"format":"jsonv2","limit":5})
    result=json.loads(fetch(SEARCH_URL+"?"+query,timeout=9).decode("utf-8"))
    if not result: raise ValueError("Адресу не знайдено: "+text)
    return result

