def load_graph():
    nodes,edges=json.loads(zlib.decompress(base64.b85decode(ROAD_DATA)).decode())
    graph=[[] for _ in nodes]
    for a,b,flags in edges:
        d=distance(nodes[a],nodes[b]);bike=bool(flags&1);walk=bool(flags&2)
        if flags&4:
            if bike:graph[a].append((b,d,True,False))
            if walk:
                graph[a].append((b,d,False,True));graph[b].append((a,d,False,True))
        elif flags&8:
            if bike:graph[b].append((a,d,True,False))
            if walk:
                graph[a].append((b,d,False,True));graph[b].append((a,d,False,True))
        else:
            graph[a].append((b,d,bike,walk));graph[b].append((a,d,bike,walk))
    return nodes,graph


def nearest(nodes,point,graph,ride_only=False):
    # Spatial bins avoid scanning the whole city on every click.
    la,lo=point; best=[]
    for i,p in enumerate(nodes):
        if abs(p[0]-la)>.012 or abs(p[1]-lo)>.018:continue
        if ride_only and not any(e[2] for e in graph[i]):continue
        d=distance(p,point)
        if len(best)<10:
            heapq.heappush(best,(-d,i))
        elif d < -best[0][0]:heapq.heapreplace(best,(-d,i))
    if not best:raise ValueError('Поблизу точки немає доріг у завантаженій області')
    return sorted([(-d,i) for d,i in best])


def turn_left(nodes,prev,cur,nxt):
    if prev<0:return False
    a,b,c=nodes[prev],nodes[cur],nodes[nxt]
    scale=math.cos(math.radians(b[0]))
    x1=(b[1]-a[1])*scale;y1=b[0]-a[0]
    x2=(c[1]-b[1])*scale;y2=c[0]-b[0]
    cross=x1*y2-y1*x2;dot=x1*x2+y1*y2
    angle=math.degrees(math.atan2(cross,dot))
    return angle>25


def find_route(nodes,graph,start,end,no_left=False):
    s=nearest(nodes,start,graph,True)[0][1]
    t=nearest(nodes,end,graph,True)[0][1]
    if s==t:return [(s,0)],0,0
    goal=nodes[t]
    # Cost encourages riding, permits walking where pedestrian access is mapped.
    # A left turn while RIDING is forbidden for the orange route.
    pq=[(distance(nodes[s],goal),0,(-1,s,0))]
    costs={(-1,s,0):0}; parent={}; walking={(-1,s,0):0}
    best_state=None;limit=0
    while pq:
        _,g,state=heapq.heappop(pq)
        if g>costs.get(state,float('inf'))+.00001:continue
        prev,cur,mode=state
        if cur==t:best_state=state;break
        limit+=1
        if limit>650000:raise ValueError('Пошук перевищив ліміт; вибери ближчі точки')
        for nxt,d,bike,foot in graph[cur]:
            if nxt==prev:continue
            # Bicycle mode 0, walking mode 1
            for nm in ((0,1) if no_left else (0,)):
                if nm==0 and not bike:continue
                if nm==1 and not foot:continue
                if no_left and nm==0 and mode==0 and turn_left(nodes,prev,cur,nxt):continue
                # At change from walking to riding, the next maneuver is a fresh start.
                if no_left and nm==0 and mode==1:pass
                cost=d*(1 if nm==0 else 7)
                if nm!=mode:cost+=120
                new=(cur,nxt,nm); ng=g+cost
                if ng>=costs.get(new,float('inf')):continue
                costs[new]=ng;parent[new]=state
                walking[new]=walking[state]+(d if nm==1 else 0)
                heapq.heappush(pq,(ng+distance(nodes[nxt],goal),ng,new))
    if best_state is None:raise ValueError('Дозволеного маршруту не знайдено')
    result=[];state=best_state
    while state in parent:
        result.append((state[1],state[2]));state=parent[state]
    result.append((s,0));result.reverse()
    total=sum(distance(nodes[a],nodes[b]) for (a,_),(b,_) in zip(result,result[1:]))
    return result,total,walking[best_state]



def local_route(nodes, graph, a, b, no_left=False):
    result, total, walked = find_route(nodes, graph, a, b, no_left)
    pts = [tuple(nodes[i]) for i, mode in result]
    # mode on each segment is stored at the DESTINATION node.
    walk_segments = [i for i in range(1, len(result)) if result[i][1] == 1]
    left_points = []
    for i in range(1, len(result)-1):
        prev, cur, nxt = result[i-1][0], result[i][0], result[i+1][0]
        if result[i][1] == 0 and result[i+1][1] == 0 and turn_left(nodes, prev, cur, nxt):
            left_points.append(tuple(nodes[cur]))
    if no_left and left_points:
        raise RuntimeError("Алгоритм виявив лівий поворот: маршрут відхилено")
    steps = ["Старт"]
    if walked > 0:
        steps.append(f"Вести велосипед пішки: {walked:.0f} м сумарно")
    steps.append("Фініш")
    return {"points":pts, "length":total, "walk":walked,
            "walk_segments":walk_segments, "left":len(left_points),
            "left_points":left_points, "steps":steps}


# Worldwide routing: request only the selected area's OSM roads, never a world-sized graph.
# For long journeys the public bicycle router supplies the blue route; a strict
# no-left-turn red route is attempted only when a manageable local graph is available.
DYNAMIC_GRAPH_CACHE={}

def bbox_for(a,b):
    mid=(a[0]+b[0])/2
    pad_lat=max(.012,abs(a[0]-b[0])*.35)
    pad_lon=max(.018,abs(a[1]-b[1])*.35)
    return (max(-85,a[0]-pad_lat if a[0]<b[0] else b[0]-pad_lat),
            min(a[1],b[1])-pad_lon,
            min(85,max(a[0],b[0])+pad_lat),
            max(a[1],b[1])+pad_lon)

def dynamic_graph(a,b):
    # Limit the download area; public Overpass servers are shared community services.
    if distance(a,b)>14000:
        raise ValueError('Червоний маршрут для відстаней понад 14 км поки недоступний')
    south,west,north,east=bbox_for(a,b)
    area=distance((south,west),(north,west))*distance((south,west),(south,east))/1e6
    if area>450:
        raise ValueError('Занадто велика ділянка для локального пошуку без лівих поворотів')
    key=tuple(round(x,3) for x in (south,west,north,east))
    if key in DYNAMIC_GRAPH_CACHE:return DYNAMIC_GRAPH_CACHE[key]
    q=f'[out:json][timeout:35];(way["highway"]({south:.6f},{west:.6f},{north:.6f},{east:.6f}););out body;>;out skel qt;'
    errors=[];data=None
    for server in OVERPASS_SERVERS:
        try:
            req=urllib.request.Request(server,data=urllib.parse.urlencode({'data':q}).encode(),headers={'User-Agent':AGENT,'Accept':'application/json'})
            with urllib.request.urlopen(req,timeout=45) as resp:data=json.load(resp)
            break
        except Exception as e:errors.append(str(e)[:90])
    if data is None:raise ValueError('Сервер дорожніх даних тимчасово недоступний: '+'; '.join(errors))
    points={el['id']:(el['lat'],el['lon']) for el in data.get('elements',[]) if el['type']=='node'}
    ids={};nodes=[];edges=[]
    excluded={'motorway','motorway_link','trunk','trunk_link','construction','proposed','raceway','steps','platform','corridor','elevator'}
    for el in data.get('elements',[]):
        if el['type']!='way':continue
        tags=el.get('tags',{}); highway=tags.get('highway','')
        if highway in excluded:continue
        access=tags.get('access',''); bicycle=tags.get('bicycle','');foot=tags.get('foot','')
        if access in ('private','no') and bicycle not in ('yes','designated','permissive') and foot not in ('yes','designated','permissive'):continue
        bike=highway not in ('footway','pedestrian','bridleway') and bicycle not in ('no','private','dismount')
        if bicycle in ('yes','designated','permissive'):bike=True
        walk=foot not in ('no','private') and highway not in ('motorway','motorway_link')
        if not bike and not walk:continue
        oneway=tags.get('oneway','no')
        if tags.get('junction')=='roundabout' and oneway=='no':oneway='yes'
        if tags.get('oneway:bicycle') in ('no','0','false'):oneway='no'
        if tags.get('oneway:bicycle') in ('yes','-1'):oneway=tags['oneway:bicycle']
        flags=(1 if bike else 0)|(2 if walk else 0)|(4 if oneway in ('yes','1','true') else 8 if oneway=='-1' else 0)
        valid=[nid for nid in el.get('nodes',[]) if nid in points]
        for u,v in zip(valid,valid[1:]):
            if u not in ids:ids[u]=len(nodes);nodes.append(points[u])
            if v not in ids:ids[v]=len(nodes);nodes.append(points[v])
            edges.append((ids[u],ids[v],flags))
    if not edges:raise ValueError('У вибраній місцевості немає доступних доріг OSM')
    graph=[[] for _ in nodes]
    for u,v,flags in edges:
        d=distance(nodes[u],nodes[v]);bike=bool(flags&1);walk=bool(flags&2)
        if flags&4:
            if bike:graph[u].append((v,d,True,False))
            if walk:graph[u].append((v,d,False,True));graph[v].append((u,d,False,True))
        elif flags&8:
            if bike:graph[v].append((u,d,True,False))
            if walk:graph[u].append((v,d,False,True));graph[v].append((u,d,False,True))
        else:
            graph[u].append((v,d,bike,walk));graph[v].append((u,d,bike,walk))
    if len(DYNAMIC_GRAPH_CACHE)>=3:DYNAMIC_GRAPH_CACHE.clear()
    DYNAMIC_GRAPH_CACHE[key]=(nodes,graph)
    return nodes,graph

def online_bicycle_route(a,b):
    coords=f'{a[1]:.6f},{a[0]:.6f};{b[1]:.6f},{b[0]:.6f}'
    url=BIKE_ROUTER+coords+'?overview=full&geometries=geojson&steps=false'
    result=json.loads(fetch(url,timeout=25).decode('utf-8'))
    routes=result.get('routes') or []
    if not routes:raise ValueError('Велосипедний сервер не знайшов маршруту')
    route=routes[0];pts=[(lat,lon) for lon,lat in route['geometry']['coordinates']]
    left=sum(turn_left_coords(pts[i-1],pts[i],pts[i+1]) for i in range(1,len(pts)-1))
    return {'points':pts,'length':route['distance'],'walk':0,'walk_segments':[],
            'left':left,'left_points':[],'steps':['Старт','Велосипедний маршрут OSM','Фініш']}

def turn_left_coords(a,b,c):
    scale=math.cos(math.radians(b[0]))
    x1=(b[1]-a[1])*scale;y1=b[0]-a[0]
    x2=(c[1]-b[1])*scale;y2=c[0]-b[0]
    return math.degrees(math.atan2(x1*y2-y1*x2,x1*x2+y1*y2))>25

